arguments.content:
:root {
  --color-navy: #0A1628;
  --color-green: #003F2D;
  --color-teal: #012A2D;
  --color-accent: #C39953;
  --color-accent-hover: #A88143;
  --color-gray-light: #F4F4F5;
  --color-gray-medium: #888888;
  --color-text: #333333;
  --color-white: #FFFFFF;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --font-heading: 'Playfair Display', Georgia, serif;
  --transition: all 0.3s ease;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-body);
  color: var(--color-text);
  line-height: 1.6;
  background-color: var(--color-white);
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  color: var(--color-navy);
  margin-bottom: 0.5em;
  line-height: 1.2;
}

a {
  text-decoration: none;
  color: inherit;
  transition: var(--transition);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Buttons and Links */
.cta-button {
  display: inline-block;
  padding: 16px 32px;
  background-color: var(--color-accent);
  color: var(--color-white);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  font-size: 14px;
  border: none;
  cursor: pointer;
}

.cta-button:hover {
  background-color: var(--color-accent-hover);
}

.cta-button-outline {
  background-color: transparent;
  border: 1px solid var(--color-white);
  color: var(--color-white);
}

.cta-button-outline:hover {
  background-color: var(--color-white);
  color: var(--color-navy);
}

.cta-link {
  display: inline-flex;
  align-items: center;
  color: var(--color-accent);
  font-family: var(--font-body);
  font-weight: 600;
  text-transform: uppercase;
  font-size: 13px;
  letter-spacing: 1px;
  border-bottom: 2px solid transparent;
  padding-bottom: 2px;
}

.cta-link:hover {
  border-bottom-color: var(--color-accent);
}

.cta-link::after {
  content: '→';
  margin-left: 8px;
  font-size: 16px;
}

/* Header & Announcement */
.announcement-banner {
  background-color: var(--color-teal);
  color: var(--color-white);
  text-align: center;
  padding: 12px 24px;
  font-size: 14px;
  font-weight: 500;
}

.announcement-banner a {
  color: var(--color-accent);
  text-decoration: underline;
  margin-left: 12px;
  font-weight: 600;
}

.site-header {
  background-color: var(--color-navy);
  color: var(--color-white);
  position: sticky;
  top: 0;
  z-index: 1000;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.header-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px;
  max-width: 1280px;
  margin: 0 auto;
}

.logo a {
  font-family: var(--font-heading);
  font-size: 28px;
  font-weight: 700;
  color: var(--color-white);
  letter-spacing: 1px;
}

/* Desktop Navigation */
.desktop-nav ul {
  list-style: none;
  display: flex;
  gap: 32px;
  align-items: center;
}

.desktop-nav a {
  color: var(--color-white);
  font-weight: 500;
  font-size: 15px;
}

.desktop-nav a:hover {
  color: var(--color-accent);
}

/* Mega Menu */
.has-dropdown {
  position: relative;
  padding-bottom: 24px;
  margin-bottom: -24px;
}

.mega-menu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  background: var(--color-white);
  color: var(--color-text);
  padding: 48px;
  box-shadow: 0 20px 40px rgba(0,0,0,0.15);
  opacity: 0;
  visibility: hidden;
  transition: var(--transition);
  display: flex;
  gap: 60px;
  border-top: 4px solid var(--color-accent);
}

.has-dropdown:hover .mega-menu {
  opacity: 1;
  visibility: visible;
  top: calc(100% + 24px);
}

.mega-column h4 {
  font-family: var(--font-body);
  font-size: 13px;
  color: var(--color-gray-medium);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 24px;
  border-bottom: 1px solid var(--color-gray-light);
  padding-bottom: 12px;
}

.mega-column ul {
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: flex-start;
}

.mega-column a {
  color: var(--color-navy);
  font-size: 16px;
  font-weight: 500;
}

.mega-column a:hover {
  color: var(--color-accent);
}

/* Mobile Menu Toggle */
.mobile-menu-toggle {
  display: none;
  background: none;
  border: none;
  color: var(--color-white);
  font-size: 16px;
  text-transform: uppercase;
  letter-spacing: 1px;
  font-weight: 600;
  cursor: pointer;
}

.mobile-nav {
  display: none;
  background-color: var(--color-navy);
  padding: 24px;
  border-top: 1px solid rgba(255,255,255,0.1);
}

.mobile-nav.is-open {
  display: block;
}

.accordion-item {
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.accordion-header {
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  color: var(--color-white);
  padding: 16px 0;
  font-size: 18px;
  font-family: var(--font-body);
  font-weight: 500;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
}

.accordion-content {
  display: none;
  padding-bottom: 16px;
}

.accordion-content.is-open {
  display: block;
}

.accordion-content a {
  display: block;
  color: rgba(255,255,255,0.7);
  padding: 8px 0 8px 16px;
  font-size: 15px;
}

/* Hero Section */
.hero {
  position: relative;
  padding: 160px 0;
  background-color: var(--color-navy);
  color: var(--color-white);
  background-size: cover;
  background-position: center;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to right, rgba(10, 22, 40, 0.9) 0%, rgba(10, 22, 40, 0.4) 100%);
}

.hero .container {
  position: relative;
  z-index: 2;
}

.hero-content {
  max-width: 700px;
}

.hero h1 {
  color: var(--color-white);
  font-size: 64px;
  margin-bottom: 24px;
}

.hero p {
  font-size: 20px;
  margin-bottom: 40px;
  opacity: 0.9;
  font-weight: 300;
}

/* Page Headers (Smaller Hero) */
.page-hero {
  padding: 120px 0;
}
.page-hero h1 {
  font-size: 52px;
}

/* Sections */
.section {
  padding: 96px 0;
}

.section-bg-light {
  background-color: var(--color-gray-light);
}

.section-bg-navy {
  background-color: var(--color-navy);
  color: var(--color-white);
}

.section-bg-navy h2 {
  color: var(--color-white);
}

.section-header {
  text-align: center;
  margin-bottom: 64px;
  max-width: 800px;
  margin-left: auto;
  margin-right: auto;
}

.section-header h2 {
  font-size: 40px;
  margin-bottom: 16px;
}

.section-header p {
  font-size: 18px;
  color: var(--color-gray-medium);
}

/* Grids */
.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 48px;
}

/* Cards */
.card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-light);
  transition: var(--transition);
  display: flex;
  flex-direction: column;
  height: 100%;
}

.card:hover {
  box-shadow: 0 10px 30px rgba(0,0,0,0.08);
  transform: translateY(-4px);
}

.card-image {
  width: 100%;
  height: 240px;
  object-fit: cover;
}

.card-content {
  padding: 32px;
  flex-grow: 1;
  display: flex;
  flex-direction: column;
}

.card-category {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--color-accent);
  font-weight: 600;
  margin-bottom: 12px;
}

.card h3 {
  font-size: 24px;
  margin-bottom: 16px;
}

.card p {
  color: var(--color-gray-medium);
  margin-bottom: 24px;
  flex-grow: 1;
}

/* Horizontal Tabs (What We Do) */
.tabs-container {
  display: flex;
  gap: 64px;
  background: var(--color-white);
  border: 1px solid var(--color-gray-light);
}

.tab-buttons {
  display: flex;
  flex-direction: column;
  width: 35%;
  background: var(--color-gray-light);
}

.tab-btn {
  background: none;
  border: none;
  text-align: left;
  padding: 32px 40px;
  font-size: 20px;
  font-family: var(--font-heading);
  font-weight: 600;
  color: var(--color-gray-medium);
  cursor: pointer;
  transition: var(--transition);
  border-left: 4px solid transparent;
}

.tab-btn:hover {
  color: var(--color-navy);
  background: rgba(255,255,255,0.5);
}

.tab-btn.active {
  color: var(--color-navy);
  background: var(--color-white);
  border-left-color: var(--color-accent);
}

.tab-content {
  width: 65%;
  padding: 64px 64px 64px 0;
}

.tab-pane {
  display: none;
  animation: fadeIn 0.5s ease;
}

.tab-pane.active {
  display: block;
}

.tab-pane h3 {
  font-size: 32px;
  margin-bottom: 24px;
}

.tab-pane p {
  font-size: 18px;
  color: var(--color-gray-medium);
  margin-bottom: 32px;
  max-width: 600px;
}

/* Newsletter Section */
.newsletter-section {
  text-align: center;
  padding: 80px 0;
}

.newsletter-box {
  background: var(--color-navy);
  color: var(--color-white);
  padding: 64px;
  max-width: 800px;
  margin: 0 auto;
  border-top: 4px solid var(--color-accent);
}

.newsletter-box h2 {
  color: var(--color-white);
}

.newsletter-form {
  display: flex;
  gap: 16px;
  margin-top: 32px;
  justify-content: center;
}

.newsletter-form input {
  padding: 16px 24px;
  width: 300px;
  border: none;
  font-family: var(--font-body);
  font-size: 16px;
}

/* Features List / Capabilities Grid */
.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.capability-card {
  padding: 40px;
  background: var(--color-gray-light);
  border-top: 3px solid var(--color-navy);
  transition: var(--transition);
}

.capability-card:hover {
  background: var(--color-white);
  box-shadow: 0 10px 30px rgba(0,0,0,0.08);
  border-top-color: var(--color-accent);
}

.capability-card h3 {
  font-size: 22px;
  margin-bottom: 16px;
}

.capability-card p {
  color: var(--color-gray-medium);
  margin-bottom: 24px;
}

/* Two column split */
.split-section {
  display: flex;
  align-items: center;
  gap: 64px;
}
.split-content {
  flex: 1;
}
.split-image {
  flex: 1;
}

/* Footer */
.site-footer {
  background-color: var(--color-navy);
  color: var(--color-white);
  padding: 80px 0 40px;
}

.footer-top {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 64px;
  margin-bottom: 64px;
}

.footer-brand h2 {
  color: var(--color-white);
  font-size: 28px;
  margin-bottom: 16px;
}

.footer-brand p {
  color: rgba(255,255,255,0.6);
}

.footer-links {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.footer-links h4 {
  color: var(--color-white);
  font-family: var(--font-body);
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 24px;
}

.footer-links ul {
  list-style: none;
}

.footer-links li {
  margin-bottom: 12px;
}

.footer-links a {
  color: rgba(255,255,255,0.7);
  font-size: 15px;
}

.footer-links a:hover {
  color: var(--color-accent);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 32px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: rgba(255,255,255,0.5);
  font-size: 13px;
}

.footer-legal {
  display: flex;
  gap: 24px;
}

.footer-legal a:hover {
  color: var(--color-white);
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Responsive */
@media (max-width: 1024px) {
  .desktop-nav { display: none; }
  .mobile-menu-toggle { display: block; }
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
  .capabilities-grid { grid-template-columns: repeat(2, 1fr); }
  .hero h1 { font-size: 48px; }
  .tabs-container { flex-direction: column; }
  .tab-buttons { width: 100%; flex-direction: row; overflow-x: auto; }
  .tab-btn { padding: 20px; white-space: nowrap; border-left: none; border-bottom: 4px solid transparent; }
  .tab-btn.active { border-left: none; border-bottom-color: var(--color-accent); }
  .tab-content { width: 100%; padding: 40px; }
}

@media (max-width: 768px) {
  .grid-3, .grid-2, .capabilities-grid { grid-template-columns: 1fr; }
  .hero h1 { font-size: 40px; }
  .split-section { flex-direction: column; }
  .footer-top { grid-template-columns: 1fr; }
  .footer-links { grid-template-columns: 1fr 1fr; }
  .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }
  .newsletter-form { flex-direction: column; }
  .newsletter-form input { width: 100%; }
}

document.addEventListener('DOMContentLoaded', () => {
  // Mobile Menu Toggle
  const mobileToggle = document.querySelector('.mobile-menu-toggle');
  const mobileNav = document.querySelector('.mobile-nav');

  if (mobileToggle && mobileNav) {
    mobileToggle.addEventListener('click', () => {
      mobileNav.classList.toggle('is-open');
      mobileToggle.textContent = mobileNav.classList.contains('is-open') ? 'Close' : 'Menu';
    });
  }

  // Mobile Accordion
  const accordionHeaders = document.querySelectorAll('.accordion-header');
  accordionHeaders.forEach(header => {
    header.addEventListener('click', () => {
      const content = header.nextElementSibling;
      const isOpen = content.classList.contains('is-open');

      // Close all other accordions (optional)
      document.querySelectorAll('.accordion-content').forEach(c => {
        c.classList.remove('is-open');
      });
      document.querySelectorAll('.accordion-header span').forEach(s => {
        s.textContent = '+';
      });

      if (!isOpen) {
        content.classList.add('is-open');
        header.querySelector('span').textContent = '-';
      }
    });
  });

  // What We Do Tabs
  const tabButtons = document.querySelectorAll('.tab-btn');
  const tabPanes = document.querySelectorAll('.tab-pane');

  tabButtons.forEach(button => {
    button.addEventListener('click', () => {
      // Remove active from all buttons and panes
      tabButtons.forEach(btn => btn.classList.remove('active'));
      tabPanes.forEach(pane => pane.classList.remove('active'));

      // Add active to clicked button
      button.classList.add('active');

      // Show corresponding pane
      const targetId = button.getAttribute('data-target');
      const targetPane = document.getElementById(targetId);
      if (targetPane) {
        targetPane.classList.add('active');
      }
    });
  });

  // Invest Carousel (Mock basic state change for the requirement)
  const carouselControls = document.querySelectorAll('.carousel-control');
  if (carouselControls.length > 0) {
    carouselControls.forEach(control => {
      control.addEventListener('click', (e) => {
        e.preventDefault();
        // Just mock changing state
        console.log('Carousel interacted');
        const activeItem = document.querySelector('.carousel-item.active');
        if(activeItem) {
          activeItem.classList.remove('active');
          const next = activeItem.nextElementSibling || document.querySelector('.carousel-item');
          if(next) next.classList.add('active');
        }
      });
    });
  }
});
